local SpinningWheelMaker = {}
local PRODUCTS = {
    simple_wood_spinning_wheel = { name = "Preprosto leseno predilno vreteno", woodCost = 4, ironCost = 1, time = 5, cost = 120, science = 18, happiness = 1, description = "Preprosto leseno predilno vreteno za predenje." },
    iron_banded_spinning_wheel = { name = "Železnopasno predilno vreteno", woodCost = 4, ironCost = 2, time = 7, cost = 280, science = 32, happiness = 1, prestige = 2, description = "Železnopasno predilno vreteno za trgovce." },
    silver_trimmed_spinning_wheel = { name = "Srebrnoobrobljeno predilno vreteno", woodCost = 4, silverCost = 1, ironCost = 2, time = 10, cost = 620, science = 48, happiness = 2, prestige = 6, description = "Srebrnoobrobljeno predilno vreteno za plemiče." },
    gold_trimmed_spinning_wheel = { name = "Zlatookrasno predilno vreteno", woodCost = 4, goldCost = 1, silverCost = 1, ironCost = 2, time = 14, cost = 1400, science = 62, happiness = 3, prestige = 14, description = "Zlatookrasno predilno vreteno za visoke plemiče." },
    jewel_set_spinning_wheel = { name = "Draguljasto predilno vreteno", woodCost = 4, goldCost = 1, silverCost = 1, ironCost = 2, jewelCost = 1, time = 18, cost = 3000, science = 78, happiness = 5, prestige = 27, description = "Predilno vreteno z draguljem za visoko plemstvo." },
    royal_grand_spinning_wheel = { name = "Kraljevski veliki predilno vreteno", woodCost = 6, goldCost = 2, silverCost = 2, ironCost = 2, jewelCost = 2, pearlCost = 2, time = 25, cost = 6500, science = 95, happiness = 12, prestige = 58, description = "Veliko kraljevsko predilno vreteno z biseri in zlatom za kronanje." },
}
local BUILDINGS = {
    spinning_workshop = { name = "Predilna delavnica", cost = { gold = 280, wood = 160, stone = 120, iron = 6 }, upkeep = 6, qualityBonus = 5 },
    textile_loft = { name = "Tekstilna podstrešje", cost = { gold = 1000, wood = 320, stone = 240, silver = 6, iron = 6 }, upkeep = 23, qualityBonus = 18 },
    master_spinner_atelier = { name = "Mojstrski predilni atelje", cost = { gold = 2800, wood = 380, stone = 480, silver = 32, gold = 6 }, upkeep = 65, qualityBonus = 30 },
    royal_textile_palace = { name = "Kraljevska tekstilna palača", cost = { gold = 12000, wood = 600, stone = 800, gold = 80, jewel = 18 }, upkeep = 240, qualityBonus = 55, prestigeBonus = 50 },
}
SpinningWheelMaker.woodStock = 22; SpinningWheelMaker.ironStock = 12; SpinningWheelMaker.silverStock = 6; SpinningWheelMaker.goldStock = 6; SpinningWheelMaker.jewelStock = 4; SpinningWheelMaker.pearlStock = 4
SpinningWheelMaker.productStock = {}; SpinningWheelMaker.buildings = {}; SpinningWheelMaker.maker = nil; SpinningWheelMaker.activeMaking = {}; SpinningWheelMaker.totalProducts = 0; SpinningWheelMaker.dayTimer = 0
function SpinningWheelMaker.init() SpinningWheelMaker.woodStock=22; SpinningWheelMaker.ironStock=12; SpinningWheelMaker.silverStock=6; SpinningWheelMaker.goldStock=6; SpinningWheelMaker.jewelStock=4; SpinningWheelMaker.pearlStock=4; SpinningWheelMaker.productStock={}; SpinningWheelMaker.buildings={}; SpinningWheelMaker.maker=nil; SpinningWheelMaker.activeMaking={}; SpinningWheelMaker.totalProducts=0; SpinningWheelMaker.dayTimer=0; print("[SpinningWheelMaker] Royal Spinning Wheel Maker System initialized (6 products, 4 buildings)") end
function SpinningWheelMaker.hireMaker(n,s) s=s or math.random(55,90); local c=560+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; SpinningWheelMaker.maker={name=n or ("Predilar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Predilar najet: %s (spretnost: %d)",SpinningWheelMaker.maker.name,s),"success") end; return true end
function SpinningWheelMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function SpinningWheelMaker.build(id) local ok,e=SpinningWheelMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(SpinningWheelMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function SpinningWheelMaker.getQualityBonus() local b=0; for _,bd in ipairs(SpinningWheelMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function SpinningWheelMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.woodCost and SpinningWheelMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.ironCost and SpinningWheelMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.silverCost and SpinningWheelMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and SpinningWheelMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and SpinningWheelMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and SpinningWheelMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #SpinningWheelMaker.buildings==0 then return false,"Potrebna predilna delavnica" end; if not SpinningWheelMaker.maker then return false,"Potreben predilar" end; return true end
function SpinningWheelMaker.make(pt,qty) qty=qty or 1; local ok,e=SpinningWheelMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.woodCost then SpinningWheelMaker.woodStock=SpinningWheelMaker.woodStock-d.woodCost*qty end; if d.ironCost then SpinningWheelMaker.ironStock=SpinningWheelMaker.ironStock-d.ironCost*qty end; if d.silverCost then SpinningWheelMaker.silverStock=SpinningWheelMaker.silverStock-d.silverCost*qty end; if d.goldCost then SpinningWheelMaker.goldStock=SpinningWheelMaker.goldStock-d.goldCost*qty end; if d.jewelCost then SpinningWheelMaker.jewelStock=SpinningWheelMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then SpinningWheelMaker.pearlStock=SpinningWheelMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if SpinningWheelMaker.maker then t=math.max(1,t-math.floor(SpinningWheelMaker.maker.skill/13)) end; table.insert(SpinningWheelMaker.activeMaking,{id="spinningwheel_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,science=d.science or 0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function SpinningWheelMaker.completeMaking(m) local q=1.0+(SpinningWheelMaker.getQualityBonus()/100); if SpinningWheelMaker.maker then q=q+(SpinningWheelMaker.maker.skill/140) end; q=math.min(2.5,q); SpinningWheelMaker.productStock[m.productType]=(SpinningWheelMaker.productStock[m.productType] or 0)+m.quantity; SpinningWheelMaker.totalProducts=SpinningWheelMaker.totalProducts+m.quantity; if m.science>0 and _G.state then _G.state.science=(_G.state.science or 0)+m.science end; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if SpinningWheelMaker.maker then SpinningWheelMaker.maker.itemsMade=SpinningWheelMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then SpinningWheelMaker.maker.skill=math.min(100,SpinningWheelMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Predilno vreteno izdelano: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"spinningwheel.completed",{productName=m.productName,science=m.science,prestige=m.prestige,happiness=m.happiness}) end end
function SpinningWheelMaker.update(dt) if not _G.state then return end; SpinningWheelMaker.dayTimer=SpinningWheelMaker.dayTimer+dt; if SpinningWheelMaker.dayTimer>=30 then SpinningWheelMaker.dayTimer=0; for i=#SpinningWheelMaker.activeMaking,1,-1 do local m=SpinningWheelMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then SpinningWheelMaker.completeMaking(m); table.remove(SpinningWheelMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(SpinningWheelMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if SpinningWheelMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function SpinningWheelMaker.getStats() return {woodStock=SpinningWheelMaker.woodStock,ironStock=SpinningWheelMaker.ironStock,silverStock=SpinningWheelMaker.silverStock,goldStock=SpinningWheelMaker.goldStock,jewelStock=SpinningWheelMaker.jewelStock,pearlStock=SpinningWheelMaker.pearlStock,productStock=SpinningWheelMaker.productStock,numBuildings=#SpinningWheelMaker.buildings,hasMaker=SpinningWheelMaker.maker~=nil,makerName=SpinningWheelMaker.maker and SpinningWheelMaker.maker.name or "—",makerSkill=SpinningWheelMaker.maker and SpinningWheelMaker.maker.skill or 0,activeMaking=#SpinningWheelMaker.activeMaking,totalProducts=SpinningWheelMaker.totalProducts} end
return SpinningWheelMaker
